inline RimStyle rimStyleOf(int id){auto r=findRim(canonicalRimId(id));if(!r)return RimStyle::Tuner;auto at=std::lower_bound(std::begin(RimStyleCatalog),std::end(RimStyleCatalog),r->sourceId,[](const auto& row,int key){return row.sourceId<key;});return at!=std::end(RimStyleCatalog)&&at->sourceId==r->sourceId?at->style:RimStyle::Tuner;}
